<?php
namespace App\Services;use App\Domain\Workflow\WorkflowExecutionStatus;use App\Models\{Organization,Workflow,WorkflowExecution};use DomainException;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class ExecutionAdmission
{
 public function assertAndIncrement(Workflow $workflow):void{$org=Organization::lockForUpdate()->findOrFail($workflow->organization_id);if(($org->status??'active')!=='active')throw new DomainException('organization_inactive');$active=[WorkflowExecutionStatus::Pending->value,WorkflowExecutionStatus::Running->value];if($org->max_concurrent_executions>0&&WorkflowExecution::where('organization_id',$org->id)->whereIn('status',$active)->count()>=$org->max_concurrent_executions)throw new DomainException('organization_concurrency_limit');$versionIds=$workflow->versions()->pluck('id');if($workflow->max_concurrent_executions>0&&WorkflowExecution::whereIn('workflow_version_id',$versionIds)->whereIn('status',$active)->count()>=$workflow->max_concurrent_executions)throw new DomainException('workflow_concurrency_limit');$period=now('UTC')->startOfMonth()->toDateString();DB::table('organization_execution_usage')->insertOrIgnore(['id'=>(string)Str::uuid(),'organization_id'=>$org->id,'period_start'=>$period,'execution_count'=>0,'created_at'=>now(),'updated_at'=>now()]);$usage=DB::table('organization_execution_usage')->where('organization_id',$org->id)->where('period_start',$period)->lockForUpdate()->first();if($org->monthly_execution_limit>0&&$usage->execution_count+1>$org->monthly_execution_limit)throw new DomainException('monthly_execution_quota_exceeded');DB::table('organization_execution_usage')->where('id',$usage->id)->update(['execution_count'=>$usage->execution_count+1,'updated_at'=>now()]);}
}
